import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { Interview } from '../../types/interview.types';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { useMemo } from 'react';
import EyeIcon from '@/components/icons/marketing/EyeIcon';

interface InterviewPreviewProps {
    interview: Interview | null;
    openUpdateDialog: boolean;
    setopenUpdateDialog: (open: boolean) => void;
}

export default function InterviewPreview({
    interview,
    openUpdateDialog,
    setopenUpdateDialog,
}: InterviewPreviewProps) {

    const selectedDate = useMemo(() => {
        if (!interview?.created_at) {
            return '';
        }
        const parsed = new Date(interview.created_at);
        if (Number.isNaN(parsed.getTime())) {
            return '';
        }
        return parsed.toISOString().slice(0, 10);
    }, [interview]);

    return (
        <div>
            <Dialog open={openUpdateDialog} onOpenChange={setopenUpdateDialog}>
                <DialogContent
                    dir="rtl"
                    showCloseButton={false}
                    className="max-w-[520px] rounded-xl border border-[#E8E7EA] bg-white-blue-50 p-5 sm:p-6"
                >
                    <DialogHeader className="space-y-2">
                        <DialogTitle className="text-right text-[20px] font-semibold text-[#205295]">
                            <div className="flex items-center gap-2">
                                <EyeIcon width="24" height="24" />
                                معاينة المقايلة
                            </div>
                        </DialogTitle>
                        <div className="w-full border-b border-[#E8E7EA]" />
                    </DialogHeader>

                    <div className="mt-2 grid grid-cols-1 gap-3 sm:grid-cols-2">
                        <div className="space-y-1.5">
                            <label className="text-xs text-[#625E74]">اسم المتقدم</label>
                            <Input value={interview?.name ?? ''} readOnly className="h-9 bg-white" />
                        </div>
                        <div className="space-y-1.5">
                            <label className="text-xs text-[#625E74]">الوظيفة</label>
                            <Input value={interview?.description ?? ''} readOnly className="h-9 bg-white" />
                        </div>
                        <div className="space-y-1.5">
                            <label className="text-xs text-[#625E74]">المستوى</label>
                            <Input
                                value={interview?.department?.name ?? ''}
                                readOnly
                                className="h-9 bg-white"
                                placeholder="senior"
                            />
                        </div>
                        <div className="space-y-1.5">
                            <label className="text-xs text-[#625E74]">نوع العمل</label>
                            <Input
                                value={interview?.department?.name ?? ''}
                                readOnly
                                className="h-9 bg-white"
                            />
                        </div>
                        <div className="space-y-1.5">
                            <label className="text-xs text-[#625E74]">التاريخ</label>
                            <Input type="date" value={selectedDate} readOnly className="h-9 bg-white" />
                        </div>
                        <div className="space-y-1.5">
                            <label className="text-xs text-[#625E74]">الوقت</label>
                            <Input type="time" value={selectedDate} readOnly className="h-9 bg-white" />
                        </div>
                    </div>

                    <div className="mt-5 flex justify-start">
                        <PrimaryButton
                            type="button"
                            onClick={() => setopenUpdateDialog(false)}
                            className="h-9 min-w-[120px]"
                        >
                            الغاء
                        </PrimaryButton>
                    </div>
                </DialogContent>
            </Dialog>
        </div>
    );
}
