import { EditIcon, TrashIcon } from 'lucide-react';
import { Interview } from '../../types/interview.types';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { useState } from 'react';
import InterviewPreview from './InterviewPreview';
import InterviewEvaluation from './InterviewEvaluation';

interface InterviewCardProps {
    data: Interview[];
}

export default function InterviewCard({ data }: InterviewCardProps) {
    const [openUpdateDialog, setopenUpdateDialog] = useState(false);
    const [openEvaluationDialog, setopenEvaluationDialog] = useState(false);
    const [selectedInterview, setSelectedInterview] = useState<Interview | null>(null);

    const openDialog = (interview: Interview) => {
        setSelectedInterview(interview);
        setopenUpdateDialog(true);
    };
    const openDialogEvaluation = (interview: Interview) => {
        setSelectedInterview(interview);
        setopenEvaluationDialog(true);
    };

    const getStatusStyle = (status?: string) => {
        const value = status ?? '';
        const normalizedStatus = value.trim().toLowerCase();
        if (normalizedStatus.includes('evaluat') || normalizedStatus.includes('مقيم')) {
            return 'bg-[#EDF8F2] text-[#1D9D62]';
        }

        return 'bg-[#FFF4E5] text-[#B7791F]';
    };

    const getInterviewDateParts = (dateValue?: string) => {
        const date = dateValue ? new Date(dateValue) : null;
        if (!date || Number.isNaN(date.getTime())) {
            return { day: '--', month: '--', time: '--:--' };
        }

        const day = new Intl.DateTimeFormat('ar-EG', { day: 'numeric' }).format(date);
        const month = new Intl.DateTimeFormat('ar-EG', { month: 'long' }).format(date);
        const time = new Intl.DateTimeFormat('ar-EG', {
            hour: '2-digit',
            minute: '2-digit',
            hour12: true,
        }).format(date);

        return { day, month, time };
    };

    return (
        <div className="grid grid-cols-1 gap-4 lg:grid-cols-2">
            {data?.map((interview: Interview) => {
                const dateParts = getInterviewDateParts(interview.created_at);
                const statusLabel = interview.status || 'معلق';
                return (
                    <div key={interview.id} className="rounded-2xl border border-[#E8E7EA] bg-[#FAFAFA] px-4 py-4">
                        <div className="[@media(min-width:570px)]:flex hidden items-center justify-between gap-8 [@media(min-width:570px)]:flex-row-reverse flex-col">
                            {/* Actions */}
                            <div className="flex flex-row gap-4 justify-between items-center">
                                <span
                                    className={`rounded-md px-2.5 py-1 text-[14px] font-medium leading-[20px] whitespace-nowrap ${getStatusStyle(
                                        interview.status,
                                    )}`}
                                >
                                    {statusLabel}
                                </span>

                                <div className="flex flex-col gap-4 justify-between items-end">
                                    <div className="flex items-center gap-3 text-[#D12F2F]">
                                        <button type="button" className="text-[#F04438] transition hover:opacity-80">
                                            <TrashIcon width="18" height="18" />
                                        </button>
                                        <button
                                            type="button"
                                            className="text-[#2563EB] transition hover:opacity-80"
                                            onClick={() => openDialog(interview)}
                                        >
                                            <EditIcon width="18" height="18" />
                                        </button>
                                    </div>

                                    <div className="mt-4 flex items-center justify-between">
                                        <PrimaryButton
                                            type="button"
                                            onClick={() => openDialogEvaluation(interview)}
                                            className="h-[40px] min-w-[120px] rounded-xl border border-[#D0D5DD] bg-transparent px-4 text-[18px] font-normal leading-[24px] text-[#625E74] shadow-none hover:bg-[#F3F4F6]"
                                        >
                                            تقييم
                                        </PrimaryButton>
                                    </div>
                                </div>
                            </div>

                            {/* Interview Details */}
                            <div className="flex-1 text-right">
                                <h3 className="truncate text-[20px] font-semibold leading-[28px] text-primery-blue-900">
                                    {interview.name}
                                </h3>
                                <p className="text-[16px] font-normal leading-[24px] text-[#625E74]">
                                    {interview.department?.name || interview.description || '-'}
                                </p>
                                <p className="text-[16px] font-normal leading-[24px] text-[#625E74]">
                                    {dateParts.time}
                                </p>
                            </div>

                            {/* Interview Date */}
                            <div className="shrink-0 rounded-[16px] bg-[#ECECEC] px-4 py-3 text-center min-w-[92px]">
                                <p className="text-[32px] font-semibold leading-[34px] text-[#2B5E8A]">
                                    {dateParts.day}
                                </p>
                                <p className="text-[20px] font-semibold leading-[28px] text-[#365D8B]">
                                    {dateParts.month}
                                </p>
                            </div>
                        </div>

                        {/* Mobile View */}
                        <div className="flex [@media(min-width:570px)]:hidden flex-col gap-4">
                            {/* Actions */}
                            <div className="flex items-center justify-between gap-3">
                                <span
                                    className={`rounded-md px-2.5 py-1 text-[12px] font-medium leading-[18px] whitespace-nowrap ${getStatusStyle(
                                        interview.status,
                                    )}`}
                                >
                                    {statusLabel}
                                </span>

                                <div className="flex items-center gap-2.5">
                                    <div className="flex items-center gap-3 text-[#D12F2F]">
                                        <button type="button" className="text-[#F04438] transition hover:opacity-80">
                                            <TrashIcon width="16" height="16" />
                                        </button>
                                        <button
                                            type="button"
                                            className="text-[#2563EB] transition hover:opacity-80"
                                            onClick={() => openDialog(interview)}
                                        >
                                            <EditIcon width="16" height="16" />
                                        </button>
                                    </div>

                                    <div className="flex items-center">
                                        <PrimaryButton
                                            type="button"
                                            onClick={() => openDialogEvaluation(interview)}
                                            className="h-[34px] min-w-[92px] rounded-lg border border-[#D0D5DD] bg-transparent px-3 text-[14px] font-medium leading-[20px] text-[#625E74] shadow-none hover:bg-[#F3F4F6]"
                                        >
                                            تقييم
                                        </PrimaryButton>
                                    </div>
                                </div>
                            </div>

                            <div className="flex w-full flex-row-reverse items-start justify-between gap-3">
                                {/* Interview Details */}
                                <div className="min-w-0 flex-1 text-right">
                                    <h3 className="truncate text-[16px] font-semibold leading-[24px] text-primery-blue-900">
                                        {interview.name}
                                    </h3>
                                    <p className="truncate text-[13px] font-normal leading-[20px] text-[#625E74]">
                                        {interview.department?.name || interview.description || '-'}
                                    </p>
                                    <p className="text-[13px] font-normal leading-[20px] text-[#625E74]">
                                        {dateParts.time}
                                    </p>
                                </div>

                                {/* Interview Date */}
                                <div className="min-w-[78px] shrink-0 rounded-[14px] bg-[#ECECEC] px-3 py-2 text-center">
                                    <p className="text-[24px] font-semibold leading-[26px] text-[#2B5E8A]">
                                        {dateParts.day}
                                    </p>
                                    <p className="text-[14px] font-semibold leading-[20px] text-[#365D8B]">
                                        {dateParts.month}
                                    </p>
                                </div>
                            </div>
                        </div>
                    </div>
                );
            })}

            <InterviewPreview
                interview={selectedInterview}
                openUpdateDialog={openUpdateDialog}
                setopenUpdateDialog={setopenUpdateDialog}
             
            />
            
            <InterviewEvaluation
                interview={selectedInterview}
                openEvaluationDialog={openEvaluationDialog}
                setopenEvaluationDialog={setopenEvaluationDialog}
                allInterviews={data}
                onSelectInterview={setSelectedInterview}
            />
        </div>
    );
}
